c(22, "§3.5 table (verbatim); §5.5; §8.1 F3", "must-have", "Defects, friction and the support gap — 16 (7.41%), mean 1.81; 'the product is barely reported as broken' (verbatim): " + table("## 3.5 Defects, friction and the support gap", 0) + " — read the support theme, not the crash theme: two crash reports in 750 days (both 2024-10, within five days, never again — most consistent with one bad build) is a low defect rate; seven reviewers using a 1★ public review as a help desk is the absence of a visible support path, six of the seven about money; the one who tried the proper route ('asked this question of the developer and awaiting the reply') sits at 3★, the other six went straight to 1★; F3: put an in-app support route in front of the review prompt, and answer it — seven support tickets became permanent public 1★ reviews", "no visible support route; review prompt reached first", "1★-burst", "review-as-support 7 (3.24%) at 1.43★; crash 2 (0.93%)", "must-have", "very strong", "generalisable", ["11548752988","11583074924","11645468255","11770422740","12046853210","12149341496","13251351092","11789667295","11802262343","11971799940","11839657635","11910326853","11774398931"])
